import * as YAML from 'yaml';

// A push trigger with none of these matches every tag push as well as every
// branch push, so a workflow that pushes its own tags starts itself again.
export const FILTERS = ['branches', 'branches-ignore', 'tags', 'tags-ignore'];

export interface Finding {
	// 1-based, and it points at the `on:` key or the `push:` key under it.
	line: number;
	column: number;
}

// The one sentence this check says, with no file in it, so a caller that
// already names the file does not say it twice.
export const REMEDY =
	'its push trigger names no ref filter, so every tag push starts this workflow again. ' +
	"Add `branches: ['**']` under `push:` (or `tags-ignore: ['**']`) to keep it on branch pushes.";

export function formatFinding(file: string): string {
	return `${file}: ${REMEDY}`;
}

function isMap(node: unknown): node is YAML.YAMLMap {
	return YAML.isMap(node);
}

// The `on` value, plus the node the finding points at. YAML 1.2's core schema
// leaves `on` a plain string, so the key is read literally and never as the
// boolean YAML 1.1 would make of it.
function onEntry(doc: YAML.Document.Parsed): {key: YAML.Node; value: unknown} | undefined {
	const root = doc.contents;
	if (!isMap(root)) {
		return undefined;
	}
	for (const item of root.items) {
		if (YAML.isScalar(item.key) && item.key.value === 'on') {
			return {key: item.key as YAML.Node, value: item.value};
		}
	}
	return undefined;
}

// True when this `on:` value starts the workflow on a push that no ref filter
// narrows. Mirrors the four shapes the trigger can take: a bare `on: push`, a
// sequence naming push, a mapping whose `push` is empty, and a mapping whose
// `push` carries keys but none of the filters.
function namesAnUnfilteredPush(value: unknown): boolean {
	if (YAML.isScalar(value)) {
		return value.value === 'push';
	}
	if (YAML.isSeq(value)) {
		return value.items.some(item => YAML.isScalar(item) && item.value === 'push');
	}
	if (!isMap(value)) {
		return false;
	}
	const push = value.items.find(item => YAML.isScalar(item.key) && item.key.value === 'push');
	if (push === undefined) {
		return false;
	}
	if (!isMap(push.value)) {
		// `push:` with nothing under it, or with a scalar. Neither filters.
		return true;
	}
	return !push.value.items.some(item => YAML.isScalar(item.key) && FILTERS.includes(String(item.key.value)));
}

// The node the reader must edit: the `push:` key when there is one, and the
// `on:` key otherwise.
function anchorOf(entry: {key: YAML.Node; value: unknown}): YAML.Node {
	if (isMap(entry.value)) {
		const push = entry.value.items.find(item => YAML.isScalar(item.key) && item.key.value === 'push');
		if (push !== undefined) {
			return push.key as YAML.Node;
		}
	}
	return entry.key;
}

// Every finding in one workflow file. Never throws: a file the YAML parser
// rejects contributes nothing, the same as every sibling check.
export function scanWorkflowYaml(content: string): Finding[] {
	const lineCounter = new YAML.LineCounter();
	let doc: YAML.Document.Parsed;
	try {
		doc = YAML.parseDocument(content, {lineCounter});
	} catch {
		return [];
	}
	// parseDocument collects errors rather than throwing, so a file the parser
	// rejects still yields a partial tree. Reporting from one would mean judging
	// a document nobody can say the shape of.
	if (doc.errors.length > 0) {
		return [];
	}
	const entry = onEntry(doc);
	if (entry === undefined || !namesAnUnfilteredPush(entry.value)) {
		return [];
	}
	const anchor = anchorOf(entry);
	const offset = anchor.range ? anchor.range[0] : 0;
	const position = lineCounter.linePos(offset);
	return [{line: position.line, column: position.col}];
}

// True for a workspace-relative path this check reads. The rule is about
// workflow triggers, so an action.yml is out of scope by construction.
export function isWorkflowFile(file: string): boolean {
	return /^\.github\/workflows\/[^/]+\.ya?ml$/.test(file.replace(/\\/g, '/'));
}
